            $AdditionalFields = $JsonParameters.PSobject.Properties["additional_fields"].value
        }

        if (!([bool]($JsonParameters.PSobject.Properties.name -match "custom_fields"))) { #optional property not found
            $CustomFields = $null
        } else {
            $CustomFields = $JsonParameters.PSobject.Properties["custom_fields"].value
        }

        $PSO = [PSCustomObject]@{
            "id" = ${Id}
            "type" = ${Type}
            "u_model" = ${UModel}
            "u_sku" = ${USku}
            "name" = ${Name}
            "description" = ${Description}
            "short_description" = ${ShortDescription}
            "price" = ${Price}
            "advanced_price" = ${AdvancedPrice}
            "cost_price" = ${CostPrice}
            "quantity" = ${Quantity}
            "inventory" = ${Inventory}
            "group_items" = ${GroupItems}
            "u_brand_id" = ${UBrandId}
            "u_brand" = ${UBrand}
            "categories_ids" = ${CategoriesIds}
            "stores_ids" = ${StoresIds}
            "url" = ${Url}
            "seo_url" = ${SeoUrl}
            "meta_title" = ${MetaTitle}
            "meta_keywords" = ${MetaKeywords}
            "meta_description" = ${MetaDescription}
            "avail_sale" = ${AvailSale}
            "avail_view" = ${AvailView}
            "is_virtual" = ${IsVirtual}
            "is_downloadable" = ${IsDownloadable}
            "weight" = ${Weight}
            "weight_unit" = ${WeightUnit}
            "sort_order" = ${SortOrder}
            "in_stock" = ${InStock}
            "backorders" = ${Backorders}
            "manage_stock" = ${ManageStock}
            "is_stock_managed" = ${IsStockManaged}
            "create_at" = ${CreateAt}
            "modified_at" = ${ModifiedAt}
            "tax_class_id" = ${TaxClassId}
            "special_price" = ${SpecialPrice}
            "tier_price" = ${TierPrice}
            "group_price" = ${GroupPrice}
            "images" = ${Images}
            "product_options" = ${ProductOptions}
            "u_upc" = ${UUpc}
            "u_mpn" = ${UMpn}
            "u_gtin" = ${UGtin}
            "u_isbn" = ${UIsbn}
            "u_ean" = ${UEan}
            "related_products_ids" = ${RelatedProductsIds}
            "up_sell_products_ids" = ${UpSellProductsIds}
            "cross_sell_products_ids" = ${CrossSellProductsIds}
            "dimensions_unit" = ${DimensionsUnit}
            "width" = ${Width}
            "height" = ${Height}
            "length" = ${Length}
            "discounts" = ${Discounts}
            "additional_fields" = ${AdditionalFields}
            "custom_fields" = ${CustomFields}
        }

        return $PSO
    }

}

